INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A coluna vertebral é composta por diferentes tipos de vértebras com características regionais específicas. Qual característica é EXCLUSIVA das vértebras CERVICAIS?","options":{"a":"Processo espinhoso longo e descendente.","b":"Fóveas costais no corpo vertebral.","c":"Forames transversários nos processos transversos.","d":"Corpo vertebral volumoso e reniforme.","e":"Processos mamilares."},"answer":"c","rationale":"Os forames transversários permitem a passagem das artérias vertebrais, uma característica distintiva das vértebras C1 a C7.","option_rationales":{"a":"Errada. Característica típica das torácicas.","b":"Errada. Exclusiva das torácicas para articulação com as costelas.","c":"Correta. Anatomia regional da coluna vertebral.","d":"Errada. Típico das lombares.","e":"Errada. Presente nas lombares."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Osteologia"]}', 'f73beb1cd1a9988563eafd3ca586ded5', 300, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A primeira vértebra cervical (C1) é conhecida como Atlas. Qual característica anatômica fundamental diferencia o Atlas de quase todas as outras vértebras?","options":{"a":"Possui um processo espinhoso bífido.","b":"Não possui corpo vertebral nem processo espinhoso.","c":"Possui o processo odontoide.","d":"Articula-se diretamente com a 1ª costela.","e":"É a única vértebra sem forame vertebral."},"answer":"b","rationale":"O Atlas é um anel ósseo composto por arcos anterior e posterior e massas laterais, sem corpo ou processo espinhoso verdadeiro.","option_rationales":{"a":"Errada.","b":"Correta. Morfologia especial da transição craniocervical.","c":"Errada. O dente (processo odontoide) pertence ao Áxis (C2).","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Osteologia"]}', '928804a8553115ebb180adcb9930d533', 301, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O disco intervertebral atua como amortecedor entre as vértebras. Ele é composto por uma região central gelatinosa e um anel periférico fibroso. Como se chama a parte CENTRAL do disco?","options":{"a":"Anel fibroso.","b":"Núcleo pulposo.","c":"Ligamento amarelo.","d":"Fáscia toracolombar.","e":"Processo articular."},"answer":"b","rationale":"O núcleo pulposo é rico em água e proteoglicanos, conferindo elasticidade e resistência à compressão.","option_rationales":{"a":"Errada. É a parte externa.","b":"Correta. Histologia e anatomia funcional da coluna.","c":"Errada. Conecta as lâminas vertebrais.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Artrologia"]}', '1af427a36284a14be4c9286a8662a476', 302, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As curvaturas da coluna vertebral são classificadas como primárias ou secundárias. Qual das seguintes é uma curvatura SECUNDÁRIA (adquirida após o nascimento)?","options":{"a":"Cifose torácica.","b":"Cifose sacral.","c":"Lordose lombar.","d":"Escoliose.","e":"Nenhuma das anteriores."},"answer":"c","rationale":"As lordoses (cervical e lombar) surgem quando a criança começa a sustentar a cabeça e a andar, respectivamente.","option_rationales":{"a":"Errada. É primária (presente no feto).","b":"Errada. É primária.","c":"Correta. Desenvolvimento ontofisiológico da coluna.","d":"Errada. É uma curvatura patológica lateral.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Osteologia/Desenvolvimento"]}', 'a0934259f018f75ca198084059acbf9e', 303, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A medula espinal termina em uma extremidade afilada nos adultos. Em qual nível vertebral médio localiza-se o ''CONE MEDULAR''?","options":{"a":"L1-L2.","b":"L4-L5.","c":"T10-T11.","d":"S1-S2.","e":"C7-T1."},"answer":"a","rationale":"Nos adultos, a medula termina habitualmente no nível do disco intervertebral L1-L2. Abaixo disso, encontra-se a cauda equina.","option_rationales":{"a":"Correta. Referência fundamental para realização de punção lombar (segurança).","b":"Errada. Nível comum para coleta de líquor, por estar abaixo da medula.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Neuroanatomia"]}', 'b6c2f336e388543aa11d2e43c89ebce5', 304, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Existem diversos ligamentos que estabilizam a coluna. Qual ligamento impede a HIPEREXTENSÃO da coluna vertebral, percorrendo a face anterior dos corpos vertebrais?","options":{"a":"Ligamento longitudinal posterior.","b":"Ligamento longitudinal anterior.","c":"Ligamento amarelo.","d":"Ligamento interespinhal.","e":"Ligamento nucal."},"answer":"b","rationale":"O ligamento longitudinal anterior é a única estrutura ligamentar que limita a extensão excessiva da coluna.","option_rationales":{"a":"Errada. Limita a flexão e protege contra hérnias centrais.","b":"Correta. Biomecânica dos ligamentos espinais.","c":"Errada. Limita a flexão lateral e a separação das lâminas.","d":"Errada.","e":"Errada. Presente na região cervical posterior."},"difficulty":"Média","tags":["Anatomia","Dorso","Artrologia"]}', '1d5729686d52d2d7ef03135917dd334b', 305, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As meninges protegem a medula espinal. Como se denomina o espaço entre a pia-máter e a aracnoide-máter, onde circula o líquido cerebrospinal (líquor)?","options":{"a":"Espaço epidural (extradural).","b":"Espaço subdural.","c":"Espaço subaracnoideo.","d":"Canal central da medula.","e":"Cisterna magna."},"answer":"c","rationale":"O espaço subaracnoideo contém o líquor e vasos sanguíneos, protegendo o sistema nervoso central.","option_rationales":{"a":"Errada. Local de gordura e plexos venosos, externo à dura-máter.","b":"Errada. Espaço virtual entre dura e aracnoide.","c":"Correta. Anatomia das meninges.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Neuroanatomia"]}', '4a25ecbb40c39127de744705bb5b4bd4', 306, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''cauda equina'' é o conjunto de raízes nervosas que se estende abaixo do cone medular. De quais segmentos medulares derivam essas raízes?","options":{"a":"Apenas lombares.","b":"Lombares, sacrais e coccígeos.","c":"Apenas sacrais.","d":"Torácicos inferiores e lombares.","e":"Apenas coccígeos."},"answer":"b","rationale":"Como a medula é mais curta que a coluna óssea, as raízes dos níveis inferiores precisam descer verticalmente para atingir seus respectivos forames.","option_rationales":{"a":"Errada.","b":"Correta. Organização do sistema nervoso periférico espinal.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Neuroanatomia"]}', '90794ee03a5def836cb710c3b8e8540f', 307, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo TRAPÉZIO é um músculo superficial do dorso. Qual o nervo responsável pela sua inervação MOTORA?","options":{"a":"Nervo dorsal da escápula.","b":"Nervo acessório (XI par craniano).","c":"Nervos intercostais.","d":"Nervo torácico longo.","e":"Nervo axilar."},"answer":"b","rationale":"O trapézio é inervado pelo nervo acessório, o que explica sua função mesmo em lesões medulares cervicais baixas.","option_rationales":{"a":"Errada. Inerva os levantadores e romboides.","b":"Correta. Neuroanatomia funcional aplicada.","c":"Errada.","d":"Errada. Inerva o serrátil anterior.","e":"Errada. Inerva o deltoide."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Neuroanatomia/Miologia"]}', '7df2f0ad1b006b7b6d1d5051d2a12e21', 308, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A hérnia de disco ocorre quando o núcleo pulposo extravasa através do anel fibroso. Em qual direção a maioria das hérnias discais ocorre, devido à anatomia dos ligamentos longitudinais?","options":{"a":"Anterior.","b":"Posterolateral.","c":"Posterior central.","d":"Lateral pura.","e":"Superior."},"answer":"b","rationale":"O ligamento longitudinal posterior é mais forte no centro, direcionando o material herniado para as áreas laterais mais fracas, onde comprimem as raízes nervosas.","option_rationales":{"a":"Errada. Rara devido à força do ligamento longitudinal anterior.","b":"Correta. Anatomia aplicada à patologia da coluna.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Clínica/Artrologia"]}', '31444811cb6454e4c8d27e290a5cf552', 309, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''ligamento amarelo'' conecta quais partes de vértebras adjacentes?","options":{"a":"Corpos vertebrais.","b":"Processos espinhosos.","c":"Lâminas.","d":"Processos transversos.","e":"Pedículos."},"answer":"c","rationale":"O ligamento amarelo é elástico e ajuda a manter as curvaturas e a retornar à posição ereta após a flexão.","option_rationales":{"a":"Errada. Ligados pelos longitudinais.","b":"Errada. Ligados pelos supra e interespinhais.","c":"Correta. Estrutura de fechamento do canal vertebral.","d":"Errada. Ligados pelos intertransversários.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Artrologia"]}', '0e333c92d0e0c293741dc3d0de6a68d3', 310, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual músculo do dorso, pertencente ao grupo profundo (intrínseco), é o principal extensor da coluna vertebral e é dividido em três colunas (iliocostal, longuíssimo e espinal)?","options":{"a":"Latíssimo do dorso.","b":"Eretor da espinha.","c":"Serrátil posterior.","d":"Multífido.","e":"Esplênio da cabeça."},"answer":"b","rationale":"A massa muscular eretora da espinha é o motor primário para a extensão e manutenção da postura ereta.","option_rationales":{"a":"Errada. Músculo superficial do membro superior.","b":"Correta. Miologia profunda do dorso.","c":"Errada.","d":"Errada. Músculo mais profundo, rotador.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Miologia"]}', '1b457d332fd9442e9e46523967e369f2', 311, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''atlas'' (C1) e o ''áxis'' (C2) articulam-se permitindo a rotação da cabeça (''gesto de não''). Qual ligamento é fundamental para manter o dente do Áxis em posição contra o arco anterior do Atlas?","options":{"a":"Ligamento Alar.","b":"Ligamento Transverso do Atlas.","c":"Membrana tectorial.","d":"Ligamento do ápice do dente.","e":"Ligamento longitudinal posterior."},"answer":"b","rationale":"O ligamento transverso é a parte mais importante do complexo cruciforme, impedindo a luxação atlantoaxial posterior.","option_rationales":{"a":"Errada. Limitam a rotação.","b":"Correta. Biomecânica da coluna cervical alta.","c":"Errada. Continuação cefálica do logitude posterior.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Artrologia/Biomecânica"]}', 'f6a9f83d3550285c8f2014694e41de0a', 312, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As raízes nervosas espinais emergem da coluna vertebral através de qual abertura?","options":{"a":"Forame vertebral.","b":"Forame intervertebral.","c":"Forame transverso.","d":"Hiato sacral.","e":"Canal sacral."},"answer":"b","rationale":"O forame intervertebral é formado pela sobreposição das incisuras vertebrais superior e inferior de pedículos adjacentes.","option_rationales":{"a":"Errada. Onde fica a medula.","b":"Correta. Anatomia da saída nervosa.","c":"Errada. Passagem da artéria vertebral na cervical.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Osteologia"]}', 'fed85969584e12e85c6ffdbce9dd08b0', 313, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''punção lombar'' para coleta de líquor é realizada preferencialmente entre quais vértebras para evitar lesão medular?","options":{"a":"T12-L1.","b":"L1-L2.","c":"L3-L4 ou L4-L5.","d":"L5-S1.","e":"S1-S2."},"answer":"c","rationale":"Como a medula termina em L1-L2, níveis abaixo de L3 são seguros para a introdução da agulha no espaço subaracnoideo.","option_rationales":{"a":"Errada.","b":"Errada. Risco de atingir o cone medular.","c":"Correta. Procedimento clínico baseado em anatomia topográfica.","d":"Errada. Mais difícil tecnicamente.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Clínica/Neuroanatomia"]}', '61ee5ae55695facf3b1041bc1fb39754', 314, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual característica morfológica ajuda a identificar uma vértebra como sendo LOMBAR?","options":{"a":"Corpo pequeno e forame vertebral triangular.","b":"Processo espinhoso horizontal e quadrilátero.","c":"Fóveas costais transversárias.","d":"Corpo em forma de coração.","e":"Processo espinhoso longo e muito inclinado."},"answer":"b","rationale":"As vértebras lombares têm processos espinhosos curtos, robustos e retangulares, adaptados para fixação de grandes músculos.","option_rationales":{"a":"Errada. Característica cervical.","b":"Correta. Morfologia vertebral regional.","c":"Errada. Característica torácica.","d":"Errada. Característica torácica.","e":"Errada. Característica torácica."},"difficulty":"Média","tags":["Anatomia","Dorso","Osteologia"]}', '4f9337404aab4c3180e44224752f6fec', 315, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O hiato sacral, utilizado para anestesia caudal, representa a ausência de quais estruturas na 5ª vértebra sacral (S5)?","options":{"a":"Corpo e pedículos.","b":"Lâminas e processo espinhoso.","c":"Processos transversos.","d":"Forames sacrais.","e":"Promontório."},"answer":"b","rationale":"O fracasso na fusão das lâminas de S5 (e às vezes S4) cria uma abertura natural para o canal sacral.","option_rationales":{"a":"Errada.","b":"Correta. Marco anatômico para anestesia regional epidural.","c":"Errada.","d":"Errada.","e":"Errada. Marco de S1."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Osteologia/Anestesia"]}', 'ea945102eed8e18c3b21a9d12bd151f8', 316, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As artérias vertebrais, ramos das artérias subclávias, entram nos forames transversários em qual nível?","options":{"a":"C1.","b":"C6.","c":"C7.","d":"T1.","e":"Base do crânio diretamente."},"answer":"b","rationale":"Apesar de C7 possuir forame transverso, a artéria vertebral geralmente entra no de C6 e sobe até C1 antes de penetrar no crânio.","option_rationales":{"a":"Errada.","b":"Correta. Trajeto vascular cervical.","c":"Errada. C7 costuma conter apenas veias vertebrais acessórias.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso/Pescoço","Angiologia"]}', '3693a51c945d58c4e7d2be2ffe2b1567', 317, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''filum terminale'' é uma estrutura delgada que ancora o cone medular ao cóccix. De qual meninge ele é composto principalmente?","options":{"a":"Dura-máter.","b":"Aracnoide-máter.","c":"Pia-máter.","d":"Ependimócitos.","e":"Tecido adiposo epidural."},"answer":"c","rationale":"O filum terminale interno é uma extensão da pia-máter.","option_rationales":{"a":"Errada. Forma o filum terminale externo após o saco dural.","b":"Errada.","c":"Correta. Fixação da medula espinal.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Neuroanatomia"]}', 'faec59ebf1f5646e5e5d2f7c46cf44c1', 318, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os músculos suboccipitais formam um trígono na região cervical alta. Qual estrutura importante passa por dentro desse trígono além do nervo suboccipital?","options":{"a":"Artéria carótida.","b":"Artéria vertebral.","c":"Veia jugular interna.","d":"Nervo vago.","e":"Tronco braquiocefálico."},"answer":"b","rationale":"Após sair do forame transverso de C1, a artéria vertebral curva-se sobre o arco posterior do atlas dentro do trígono suboccipital.","option_rationales":{"a":"Errada.","b":"Correta. Relação anatômica crítica da base do crânio.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso/Pescoço","Topografia/Angiologia"]}', '08f2e24dbe9f8ba822b9a036d1e56eb6', 319, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''espondilólise'' é uma fratura de estresse em uma parte específica da vértebra lombar, comum em atletas. Que parte é essa?","options":{"a":"Corpo vertebral.","b":"Pars interarticularis (Istmo).","c":"Processo espinhoso.","d":"Lâmina.","e":"Pedículo."},"answer":"b","rationale":"A pars interarticularis localiza-se entre os processos articulares superior e inferior. Sua fratura bilateral pode levar à espondilolistese (escorregamento da vértebra).","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada à ortopedia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Ortopedia"]}', 'bd1d917da2389591d1b63f05b928945d', 320, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual dos seguintes músculos NÃO faz parte do grupo superficial do dorso (que atua no membro superior)?","options":{"a":"Trapézio.","b":"Latíssimo do dorso.","c":"Levantador da escápula.","d":"Serrátil posterior superior.","e":"Romboides."},"answer":"d","rationale":"Os serráteis posteriores pertencem ao grupo intermediário e têm função respiratória acessória (proprioceptiva).","option_rationales":{"a":"Errada. É superficial.","b":"Errada. É superficial.","c":"Errada. É superficial.","d":"Correta. Classificação muscular do dorso.","e":"Errada. São superficiais."},"difficulty":"Média","tags":["Anatomia","Dorso","Miologia"]}', '0091f1968042b0355ad8ce490c08df7e', 321, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A membrana tectorial é a continuação cefálica de qual ligamento ao entrar no forame magno?","options":{"a":"Ligamento longitudinal anterior.","b":"Ligamento longitudinal posterior.","c":"Ligamento amarelo.","d":"Ligamento nucal.","e":"Ligamento interespinhal."},"answer":"b","rationale":"O ligamento longitudinal posterior torna-se a membrana tectorial sobre o áxis e atlas.","option_rationales":{"a":"Errada.","b":"Correta. Mudança de nomenclatura anatômica na transição cervical-occipital.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Artrologia"]}', '0ecad57d10b69e8cdd88fa0f89267efa', 322, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''ligamento nucal'' é uma estrutura elástica potente que se estende da protuberância occipital externa até qual vértebra?","options":{"a":"C1.","b":"C2.","c":"C7.","d":"T12.","e":"L1."},"answer":"c","rationale":"O ligamento nucal substitui os ligamentos interespinhais e supraespinhais na região cervical, suportando o peso da cabeça.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Anatomia da região posterior do pescoço.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso/Pescoço","Artrologia"]}', '894ae36b59a8542d5af0563bfde3f99f', 323, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Onde se localiza o corpo celular dos neurônios SENSITIVOS que entram na medula espinal?","options":{"a":"Corno anterior da medula.","b":"Gânglio da raiz dorsal (espinhal).","c":"Corno posterior da medula.","d":"Córtex cerebral.","e":"Plexo celíaco."},"answer":"b","rationale":"Os neurônios sensitivos primários são pseudounipolares e seus corpos situam-se no gânglio da raiz dorsal, fora do SNC propriamente dito.","option_rationales":{"a":"Errada. Local de neurônios motores.","b":"Correta. Organização do sistema nervoso espinal.","c":"Errada. Local de sinapse e interneurônios.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Neuroanatomia"]}', '79fed89386085ff4ad01ee06413f5af1', 324, 'draft');